SELECT id, batch_id, pallet_id, uid, udi, product_name, spec, product_code, production_batch_number,
       production_date, remark, scan_status, scan_time, scan_location, invalid_flag, created_at
FROM dbo.produce_goods
WHERE uid = #{uid}
  AND invalid_flag = '0'

  AND batch_id = #{batchId}

SELECT id, batch_id, pallet_id, uid, udi, product_name, spec, product_code, production_batch_number, production_date, remark, scan_status, scan_time, scan_location, invalid_flag, created_at FROM dbo.produce_goods WHERE invalid_flag = '0' AND pallet_id IN
#{pid}
ORDER BY pallet_id ASC, id ASC
